const inp = $json || {};
const raw = (inp.raw_value === undefined || inp.raw_value === null) ? "" : String(inp.raw_value);
return [{ json: {
  raw_value: raw,
  attribute_type: inp.attribute_type || "",
  taxonomy_version: inp.taxonomy_version || "v1"
} }];

const t = $("When Called").first().json;
const p = $("Prepare").first().json;
const raw = (t.raw_value === undefined || t.raw_value === null) ? "" : String(t.raw_value);
const norm = raw.trim().toLowerCase();
const attrType = p.attribute_type;
const version = p.taxonomy_version;

const attrRows = $("Get Attribute Candidates").all().map(i => i.json).filter(r => r && r.canonical_id);
const synRows = $("Get Synonym Candidates").all().map(i => i.json).filter(r => r && r.canonical_id && r.synonym);

const result = {
  raw_value: raw,
  attribute_type: attrType,
  taxonomy_version: version,
  matched: false,
  canonical_id: "",
  canonical_value: raw,
  normalized_value: raw,
  confidence: 0,
  mapping_rule: "none",
  category: ""
};

if (norm) {
  const exact = attrRows.find(r => String(r.canonical_value || "").trim().toLowerCase() === norm);
  if (exact) {
    result.matched = true;
    result.canonical_id = exact.canonical_id;
    result.canonical_value = exact.canonical_value;
    result.normalized_value = exact.canonical_value;
    result.confidence = (exact.default_confidence === undefined || exact.default_confidence === null) ? 0.9 : exact.default_confidence;
    result.mapping_rule = "exact";
    result.category = exact.category || "";
  } else {
    const syn = synRows.find(r => String(r.synonym || "").trim().toLowerCase() === norm);
    if (syn) {
      const canon = attrRows.find(r => r.canonical_id === syn.canonical_id);
      result.matched = true;
      result.canonical_id = syn.canonical_id;
      result.canonical_value = canon ? canon.canonical_value : syn.canonical_id;
      result.normalized_value = canon ? canon.canonical_value : syn.canonical_id;
      result.confidence = (syn.confidence === undefined || syn.confidence === null) ? 0.8 : syn.confidence;
      result.mapping_rule = "synonym:" + (syn.match_type || "match");
      result.category = canon ? (canon.category || "") : "";
    }
  }
}

return [{ json: result }];
